body:
{
  "pains": [
    {
      "id": "pain:salesforce-needs-an-admin",
      "statement": "Salesforce is too much CRM for a team our size: every change needs a consultant, the reps spend more time learning it than it saves, and we still pay like an enterprise.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "Screens and objects nobody on a small team understands; a field or report change that cannot be made without the admin or a consultant.",
        "operational": "They hire consultants for setup and changes, or one person becomes the part-time Salesforce admin, and the rest of the team works around the CRM instead of in it.",
        "personal": null,
        "personal_note": "No source shows what it costs the person beyond money and time; the reviews and threads stop at 'expensive', 'unwieldy' and 'waste'. Looked on Trustpilot (Salesforce 1-2 star, page 1), Teamblind and Hacker News comments."
      },
      "workflow": "In Salesforce Sales Cloud at a sub-50-person company, each time a field, report or automation has to change and only the one admin or an outside consultant can do it, and at the daily login when reps spend longer learning screens than logging deals.",
      "type": "felt",
      "confidence": "medium",
      "priority": 1,
      "felt_evidence": {
        "kind": "switching",
        "what": "Small-business buyers say they left Salesforce for another platform (one to a tool set up in about 30 minutes), and one moved to HubSpot.",
        "cites": ["src:8", "src:12", "src:14"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The Salesforce renewal date: buyers who find it too heavy try to cancel at renewal and find they were auto-renewed.",
          "cites": ["src:8"]
        },
        {
          "event": "Salesforce's mandatory platform updates and the consultant work each one brings.",
          "cites": ["src:11"]
        }
      ],
      "who_feels": ["economic_buyer", "end_user"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "As a small business, the platform is difficult, unweildy and expensive.",
              "cites": ["src:8"]
            },
            {
              "situation": "venting",
              "verbatim": "Too difficult to use, expensive and difficult to cancel.",
              "cites": ["src:9"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "We moved to another WAAAAAY better platform.",
              "cites": ["src:8"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "I think Salesforce is fine for large companies with teams of sales reps and a well staffed IT department",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Licence money plus consultant fees for a system the team does not use well.",
          "fears": "No source states the fear directly; the quotes stop at cost and difficulty.",
          "dream_outcome": "A CRM the team can set up and change themselves without paying an admin or a consultant."
        },
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "users spent more time trying learn it than any amount of time it saved.",
              "cites": ["src:10"]
            },
            {
              "situation": "venting",
              "verbatim": "It needs so much customization.",
              "cites": ["src:12"]
            },
            {
              "situation": "venting",
              "verbatim": "Any changes made to one place will require changing everything connected",
              "cites": ["src:13"]
            },
            {
              "situation": "venting",
              "verbatim": "Salesforce admin is a pain in the ass.",
              "cites": ["src:11"]
            }
          ],
          "costs_them": "Hours learning and re-wiring the CRM that should go to selling.",
          "fears": "No source states the fear; the quotes describe the time lost, not what they worry happens next.",
          "dream_outcome": "Open the CRM, log the deal, move on, with changes that do not ripple through everything else."
        }
      },
      "relief": {
        "line": "It just runs the busywork. The CRM now does the sales admin the team used to do by hand.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "the way it has automated many aspects of our sales and general business cannot be undersold.",
            "cites": ["src:14"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A different business. The owner describes the move as having changed the company, not just the tool.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "overall has made a massive transformation in our business.",
            "cites": ["src:14"]
          }
        ],
        "gap": null
      },
      "segments": ["seg:startup"],
      "feature_ref": "feat:smartcrm",
      "feature_note": "Smart CRM is HubSpot's answer to this; the one switcher found (src:14) still calls HubSpot expensive, so the relief is ease, not price.",
      "cites": ["src:8", "src:10", "src:11", "src:12"]
    },
    {
      "id": "pain:bill-jumps-on-contacts-and-seats",
      "statement": "The HubSpot bill keeps climbing on things we did not choose: a contact tier we cannot get back down from, an extra seat just to send a quote, features behind another paywall.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "A renewal or invoice at a higher marketing-contacts tier or seat count than the team thinks it is using.",
        "operational": "They cut marketing contacts, chase support for a credit, and wait for renewal to downgrade; some start pricing other CRMs.",
        "personal": null,
        "personal_note": "Reviews describe the company's cost and the decision to leave, not what it cost the person who signed off on the bill. Looked on Trustpilot HubSpot 1-2 star pages 1 and 2 and Hacker News."
      },
      "workflow": "At HubSpot renewal, when the marketing-contacts tier and seat count on the renewal quote are set in Account & Billing, and in Sales Hub when a rep without the right paid seat tries to create a quote.",
      "type": "felt",
      "confidence": "high",
      "priority": 2,
      "felt_evidence": {
        "kind": "switching",
        "what": "Paying HubSpot customers say they are leaving or not renewing over price rises and tier billing.",
        "cites": ["src:1", "src:2", "src:4"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The mailing list grows past the marketing-contacts cap on the plan.",
          "cites": ["src:3"]
        },
        {
          "event": "HubSpot starts requiring an extra paid seat to create quotes.",
          "cites": ["src:2"]
        },
        {
          "event": "The renewal quote is generated at the old contact tier before the team's cut takes effect.",
          "cites": ["src:1"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "It renewed at the old tier anyway, because a separate quote had to be activated ten days beforehand",
              "cites": ["src:1"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Recently you have to buy an extra seat just to be able to create quotes????? How??",
              "cites": ["src:2"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "6000 was the MAXIMUM number of people I could stay in touch with - ever.",
              "cites": ["src:3"]
            },
            {
              "situation": "venting",
              "verbatim": "The pricing continues to increase while the level of customer service and support has steadily declined.",
              "cites": ["src:4"]
            },
            {
              "situation": "venting",
              "verbatim": "They bury basic automation features behind unexpected, aggressive paywalls",
              "cites": ["src:5"]
            },
            {
              "situation": "when_comparing",
              "verbatim": "There are also big, all-in-one platforms like HubSpot, but they tend to be dauntingly expensive for small companies.",
              "cites": ["src:6"]
            },
            {
              "situation": "when_refusing",
              "verbatim": "Software is fine; we're leaving anyway.",
              "cites": ["src:1"]
            }
          ],
          "costs_them": "Recurring spend on contacts and seats they do not use: £142 a month in one case, €10,000 a year more in another.",
          "fears": "That the bill keeps rising every renewal with nothing they can do until the next one.",
          "dream_outcome": "A bill that moves when their usage moves, and a price they knew before they signed."
        }
      },
      "relief": {
        "line": "A bill that fits. They pay a fraction and get answered when they ask.",
        "says": [
          {
            "role": "economic_buyer",
            "verbatim": "we have moved to zoho it’s a 10th the price with excellent customer service",
            "cites": ["src:7"]
          }
        ],
        "gap": null
      },
      "euphoria": {
        "line": "Spend that tracks growth. The CRM cost stops being a line the owner argues about.",
        "says": [],
        "gap": "Read Trustpilot HubSpot 5-star page 1 and the 1-2 star switchers; the one after-state found is relief at a lower price, nobody describes the year after."
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "No HubSpot feature kills this; HubSpot's own contact-tier and seat pricing causes it. It belongs to positioning as an objection and to the offer as a pricing question, and competitors (Zoho, Brevo) are what buyers leave for.",
      "cites": ["src:1", "src:2", "src:3", "src:4"]
    },
    {
      "id": "pain:auto-renew-lock-in",
      "statement": "We missed the cancel date by a week and now we're paying for another year of a CRM we were trying to leave.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "An auto-renewal charge for a full annual term after a missed cancellation deadline, on a plan billed monthly.",
        "operational": "They argue with the account rep and support for an adjustment, get offered a discount instead, and keep paying.",
        "personal": "Paying hundreds a month for things they do not use or want, in one case while the business shrank from six staff to one.",
        "personal_note": "From src:15 and src:16; the second is the owner of a small education business."
      },
      "workflow": "In the weeks before the HubSpot or Salesforce annual renewal date, when the reminder emails land among the vendor's marketing email and the cancellation has to be filed before a contractual cut-off.",
      "type": "felt",
      "confidence": "high",
      "priority": 3,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated 2026 reviews from HubSpot and Salesforce customers describe being auto-renewed into a full term after missing a cancellation deadline.",
        "cites": ["src:15", "src:16", "src:8"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "The business shrinks and the CRM becomes an expense it no longer needs.",
          "cites": ["src:16"]
        },
        {
          "event": "The annual renewal date passes while the team is trying to cancel.",
          "cites": ["src:15"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "I missed cancelling components of my contract by a week, and it auto-renewed,",
              "cites": ["src:15"]
            },
            {
              "situation": "venting",
              "verbatim": "Being billed monthly does not mean HubSpot will allow you to cancel monthly.",
              "cites": ["src:16"]
            },
            {
              "situation": "venting",
              "verbatim": "A three year lock in that auto renews at increased prices and you cannot cancel..",
              "cites": ["src:17"]
            },
            {
              "situation": "venting",
              "verbatim": "Lets be honest, nobody reads automated reminder emails from anybody,",
              "cites": ["src:15"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "They put me (without consent) on an auto renew,",
              "cites": ["src:8"]
            }
          ],
          "costs_them": "Several thousand dollars for a year of service they had decided not to use.",
          "fears": "Collections: one owner was warned unpaid balances could go to collection.",
          "dream_outcome": "Cancel when they decide to, on the terms the billing cycle suggests."
        }
      },
      "relief": {
        "line": "Free to leave. They can stop paying the month they stop needing it.",
        "says": [],
        "gap": "Searched the same Trustpilot pages for switchers who mention flexible terms elsewhere; none describe the after-state of a CRM contract they could leave."
      },
      "euphoria": {
        "line": "No renewal dread. The renewal date stops being on the calendar at all.",
        "says": [],
        "gap": "No buyer found describing the year after leaving a locked contract."
      },
      "segments": ["seg:startup"],
      "feature_ref": null,
      "feature_note": "A contract term, not a feature. HubSpot and Salesforce both cause it; nothing in the company artifact touches it.",
      "cites": ["src:15", "src:16", "src:17"]
    },
    {
      "id": "pain:onboarding-fee-before-value",
      "statement": "They want thousands for a mandatory onboarding before we've used the thing, and then we wait days for the onboarding person to answer.",
      "element": "b2b:functional:cost_reduction",
      "shape": {
        "surface": "A one-time setup fee on the Professional quote that sales calls mandatory and non-negotiable, then slow onboarding replies.",
        "operational": "They look for alternatives or a workaround to the fee, or pay it and push implementation through emails that take 3-7 days.",
        "personal": null,
        "personal_note": "No source shows what it costs the person who signed; looked on Hacker News and Trustpilot HubSpot 1-2 star pages 1 and 2."
      },
      "workflow": "When buying HubSpot Marketing Hub Professional, at the quote step where the one-time onboarding fee appears, and then in the onboarding emails with the assigned onboarding specialist while integrations (an EHR in one case) are scoped.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A buyer asked Hacker News in March 2025 for an alternative or a workaround to HubSpot's mandatory USD 3000 setup charge.",
        "cites": ["src:18"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "Being recommended Marketing Hub Professional, which carries the mandatory one-time setup.",
          "cites": ["src:18"]
        }
      ],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {
              "situation": "when_looking",
              "verbatim": "There is apparently a USD 3000 charge for a one-time setup that is mandatory and non-negotiable.",
              "cites": ["src:18"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "Emailing with our onboarding professional left us waiting 3-7 days for a response.",
              "cites": ["src:19"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "we discovered that implementation was considerably more complicated than we had been led to expect",
              "cites": ["src:20"]
            }
          ],
          "costs_them": "Up to USD 3000 up front plus weeks of slow implementation before the tool earns anything.",
          "fears": "No source states it; the quotes stop at the fee and the delay.",
          "dream_outcome": "Start using the product the day they pay, with setup help that answers the same day."
        }
      },
      "relief": {
        "line": "Live on day one. The team is sending campaigns before the first invoice.",
        "says": [],
        "gap": "Looked in the HN thread replies and Trustpilot 5-star page 1; the only reply recommending an alternative was a vendor's own pitch (src:26), so no buyer after-state."
      },
      "euphoria": {
        "line": "Setup stops being a project. Adding a tool no longer means a quarter of onboarding.",
        "says": [],
        "gap": "No buyer found describing the after-state."
      },
      "segments": ["seg:startup"],
      "feature_ref": null,
      "feature_note": "HubSpot's own pricing term; no feature removes it.",
      "cites": ["src:18", "src:19", "src:20"]
    },
    {
      "id": "pain:support-cant-escalate",
      "statement": "When something breaks on the account we get a bot, then sales, then told to email another team ourselves.",
      "element": "b2b:ease_of_doing_business:responsiveness",
      "shape": {
        "surface": "A suspended account or a changed contact setting, and a support chat that ends without a fix.",
        "operational": "The person running the account emails Collections or another team themselves and waits, while the account stays blocked.",
        "personal": null,
        "personal_note": "Reviews describe the runaround, not what it cost the person. Looked on Trustpilot HubSpot 1-2 star pages 1 and 2."
      },
      "workflow": "In HubSpot chat support when a paid CRM account is suspended over marketing contacts, or after a licence change resets the marketing-contact setting: bot first, then Sales, then a handoff to Collections by email.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "complaining",
        "what": "October and August 2026 reviews from paying HubSpot customers describe AI-only support and chats closed without escalation.",
        "cites": ["src:21", "src:22"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A prepaid account is suspended over marketing contacts.",
          "cites": ["src:21"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "when_it_bites",
              "verbatim": "the response was essentially: email Collections yourself, wait for them to respond, and the chat was closed.",
              "cites": ["src:21"]
            },
            {
              "situation": "when_it_bites",
              "verbatim": "I only received AI support which did not solve the problem.",
              "cites": ["src:22"]
            },
            {
              "situation": "venting",
              "verbatim": "Long-term customers simply do not seem to matter anymore.",
              "cites": ["src:4"]
            }
          ],
          "costs_them": "Days locked out of a CRM they already paid for.",
          "fears": "No source states it directly; the quotes stop at the lockout and the closed chat.",
          "dream_outcome": "A human who can fix the account in the same conversation."
        }
      },
      "relief": {
        "line": "One conversation. The problem is fixed by the first person they reach.",
        "says": [],
        "gap": "src:7 praises a competitor's service in passing but about price; no buyer found describing support that fixed this."
      },
      "euphoria": {
        "line": "Trust in the vendor. They stop bracing before every support chat.",
        "says": [],
        "gap": "No buyer found describing it."
      },
      "segments": ["seg:startup"],
      "feature_ref": null,
      "feature_note": "Service Hub is for the customer's own customers; nothing in the company artifact addresses HubSpot's support of its own buyers.",
      "cites": ["src:21", "src:22", "src:4"]
    },
    {
      "id": "pain:updates-break-my-setup",
      "statement": "Every HubSpot release moves something: the things that worked get replaced, simple tasks take more clicks, and our custom setup breaks.",
      "element": "b2b:ease_of_doing_business:stability",
      "shape": {
        "surface": "Features that worked are removed or redesigned; new betas appear; daily tasks gain steps.",
        "operational": "Users relearn screens and rebuild customised workflows after each change.",
        "personal": null,
        "personal_note": "One reviewer says the tool now costs them time; nothing shows the cost to the person beyond that. Looked on Trustpilot HubSpot 1-2 star pages 1 and 2."
      },
      "workflow": "In the HubSpot CRM day to day after a platform release or a new beta, when customised views and workflows built for the business stop working the same way and routine record updates take extra steps.",
      "type": "felt",
      "confidence": "medium",
      "priority": 6,
      "felt_evidence": {
        "kind": "complaining",
        "what": "July to September 2026 reviews from HubSpot users complain that releases removed working features and slowed daily tasks.",
        "cites": ["src:23", "src:24", "src:25"]
      },
      "revealed_by": null,
      "triggers": [
        {
          "event": "A HubSpot UX release replaces features that previously worked.",
          "cites": ["src:25"]
        }
      ],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {
              "situation": "venting",
              "verbatim": "Tasks that were previously straightforward now take longer and require additional steps.",
              "cites": ["src:23"]
            },
            {
              "situation": "to_their_boss",
              "verbatim": "We purchased HubSpot to save time; it is now costing us time.",
              "cites": ["src:23"]
            },
            {
              "situation": "venting",
              "verbatim": "There always seems to be a new beta test, a new feature, or another change that makes the platform harder to navigate",
              "cites": ["src:24"]
            },
            {
              "situation": "venting",
              "verbatim": "they have removed many things that previously worked well and replaced them with a new UX features that don't work.",
              "cites": ["src:25"]
            }
          ],
          "costs_them": "Time on tasks that used to be quick, plus rework on customisations.",
          "fears": "That the next release breaks what they just rebuilt.",
          "dream_outcome": "A CRM that stays the way they set it up until they choose to change it."
        }
      },
      "relief": {
        "line": "It stays put. The screen they learned is the screen they use next month.",
        "says": [],
        "gap": "Read Trustpilot HubSpot 5-star page 1; praise is for ease in general, none describes stability after a release."
      },
      "euphoria": {
        "line": "The setup becomes an asset. Customisations compound instead of breaking.",
        "says": [],
        "gap": "No buyer found describing it."
      },
      "segments": ["seg:startup", "seg:midmarket"],
      "feature_ref": null,
      "feature_note": "HubSpot's own release cadence causes it; no feature in the company artifact addresses it.",
      "cites": ["src:23", "src:24", "src:25"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Buyers name and compare specific CRMs and say which they moved to (Zoho, another platform, HubSpot from Salesforce), so they know solutions exist.",
      "cites": ["src:7", "src:8", "src:14"]
    }
  },
  "stats": [],
  "keywords": [
    "hubspot marketing contacts tier",
    "hubspot renewal old tier",
    "hubspot extra seat to create quotes",
    "hubspot onboarding fee mandatory",
    "hubspot auto renew cancel",
    "salesforce too complicated small business",
    "salesforce admin cost",
    "hubspot price increase",
    "hubspot alternative cheaper"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the last ten first calls, which pain did the prospect name first: Salesforce being too heavy, their current tools not talking to each other, or something else?",
      "why": "The map's lead pain is ranked from public reviews; HubSpot's own sales calls would confirm or replace it.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-data-hub",
      "question": "Do buyers of Data Hub describe a specific moment when their data across tools did not match, and what tools were involved?",
      "why": "Only one old public comment (src:27) speaks to data integrity across tools; Data Hub has no pain backing it in this map.",
      "would_change": "pains[] (a new pain pointing at feat:data)"
    },
    {
      "id": "q:pains-agency",
      "question": "What do your agency partners complain about most when running HubSpot for several clients?",
      "why": "The agency segment could not be swept: HubSpot Community refused fetches and the remaining sources were vendors.",
      "would_change": "pains[].segments"
    },
    {
      "id": "q:pains-agent-hub",
      "question": "What did customers say the first time they saw Agent Hub, and what problem did they say it solves?",
      "why": "No buyer source mentions a problem Agent Hub kills; it may be a feature still looking for its pain.",
      "would_change": "pains[].feature_ref"
    },
    {
      "id": "q:pains-personal",
      "question": "When a customer leaves Salesforce for HubSpot, what do they say it was costing them personally: weekends, standing with their boss, something else?",
      "why": "The personal rung is null on most pains; it is the rung that sells.",
      "would_change": "pains[].shape.personal"
    },
    {
      "id": "q:pains-churn-reason",
      "question": "Which reason do churned customers give most: contact-tier billing, seat changes, the renewal lock-in, or support?",
      "why": "Four of the six pains are caused by HubSpot's own terms; churn data would say which costs the most.",
      "would_change": "pains[].priority"
    }
  ],
  "sources": [
    {
      "id": "src:1",
      "url": "https://trustpilot.com/reviews/6aa2d3bcf3b3feadee2d1996",
      "title": "Good software, no interest in keeping customers",
      "venue": "Trustpilot, HubSpot 1-star review, David Norman, GB",
      "speaker": "buyer",
      "published": "2026-09-10",
      "pulled": "2026-10-12",
      "verbatim": "We've paid HubSpot around £1,450 a month since 2024. In January they advised us to cut our marketing contacts to reduce the cost. We did, well before our February renewal. It renewed at the old tier anyway, because a separate quote had to be activated ten days beforehand We raised it the next day and heard nothing for six months. The eventual answer was no credit, no adjustment, wait twelve months. We're now billed £142 a month for contacts we don't use. They'd rather keep that than the account. Software is fine; we're leaving anyway."
    },
    {
      "id": "src:2",
      "url": "https://trustpilot.com/reviews/6aba25a0b0c45dc9764c02e3",
      "title": "To all new companies considering…",
      "venue": "Trustpilot, HubSpot 1-star review, Thom, NL",
      "speaker": "buyer",
